code snippet in your config:

```nix
programs.ssh.settings."*" = {
  ForwardAgent = false;
  AddKeysToAgent = "no";
  Compression = false;
  ServerAliveInterval = 0;
  ServerAliveCountMax = 3;
  HashKnownHosts = false;
  UserKnownHostsFile = "~/.ssh/known_hosts";
  ControlMaster = "no";
  ControlPath = "~/.ssh/master-%r@%n:%p";
  ControlPersist = "no";
};
```

